use std::io::*;
fn main(){let mut s=String::new();stdin().read_to_string(&mut s).unwrap();let mut v:Vec<(String,i64)>=vec![];for l in s.lines(){let p:Vec<&str>=l.split_whitespace().collect();if p.len()<2{continue;}if let Ok(x)=p[1].parse(){v.push((p[0].to_string(),x));}}if v.is_empty(){return;}let mut sc:Vec<i64>=v.iter().map(|x|x.1).collect();sc.sort();let n=sc.len();let med=if n%2==1{sc[n/2] as f64}else{(sc[n/2-1]+sc[n/2]) as f64/2.0};println!("{:.1}",med);let mx=*sc.last().unwrap();let mut names:Vec<&String>=v.iter().filter(|x|x.1==mx).map(|x|&x.0).collect();names.sort();for n in names{println!("{}",n);}}
